+export function atomicSelector(logic: BuiltLogic, name: string, inputSelectors: Selector[], compute: (...args: any[]) => any): Selector {
+  const states = statesFor(logic)
+  const selectorDependencies = new Set<string>()
+  for (const input of inputSelectors) {
+    const tagged = (input as TaggedSelector).__keaAtomic
+    if (tagged?.logic === logic && tagged.derived) selectorDependencies.add(tagged.name)
+  }
+  const state: AtomicState = {
+    name, inputSelectors, compute, dependencies: [], selectorDependencies, dependents: new Set(), evaluations: 0,
+    dirtyCause: null, hasValue: false, value: undefined, inputs: [],
+  }
+  states.set(name, state)
+  for (const dependency of selectorDependencies) states.get(dependency)?.dependents.add(name)
