+function proxify(value: any, input: number, parts: (string | number)[], path: string, record: (d: Dependency) => void): any {
+  if (value === null || (typeof value !== 'object' && typeof value !== 'function')) return value
+  if (value instanceof Map) {
+    return new Proxy(value, { get(target, property) {
+      if (property === 'get' || property === 'has') return (key: any) => {
+        record({ path: `${path}:${String(key)}`, input, parts, kind: 'map', key })
+        return target[property].call(target, key)
+      }
+      if (property === 'size') { record({ path, input, parts }); return target.size }
+      const result = Reflect.get(target, property, target)
+      return typeof result === 'function' ? result.bind(target) : result
+    }})
+  }
