+    return new Proxy(value, { get(target, property) {
+      if (property === 'has') return (key: any) => {
+        record({ path: `${path}:${String(key)}`, input, parts, kind: 'set', key })
+        return target.has(key)
+      }
+      if (property === 'size') { record({ path, input, parts }); return target.size }
+      const result = Reflect.get(target, property, target)
+      return typeof result === 'function' ? result.bind(target) : result
+    }})
+  }
+  return new Proxy(value, { get(target, property, receiver) {
