+    const result = Reflect.get(target, property, receiver)
+    // A method itself is not a state dependency. Native Array methods subsequently read the indices through this proxy.
+    if (typeof result === 'function') return result.bind(receiver)
+    if (result === null || typeof result !== 'object') record({ path: nextPath, input, parts: nextParts })
+    return proxify(result, input, nextParts, nextPath, record)
+  }})
