+function changedDependency(state: AtomicState, inputs: any[]): string | null {
+  for (const dependency of state.dependencies) {
+    const before = valueAt(state.inputs[dependency.input], dependency)
+    const after = valueAt(inputs[dependency.input], dependency)
+    if (before !== after) return dependency.path
