+    if (index >= 0 && oldInput !== inputs[index]) return `selector:${dependency}`
+  }
+  return null
+}
+
+function valueAt(value: any, dependency: Dependency): any {
+  let current = value
+  for (const part of dependency.parts) current = current == null ? undefined : current[part]
+  if (dependency.kind === 'map') return current instanceof Map ? current.get(dependency.key) : undefined
+  if (dependency.kind === 'set') return current instanceof Set ? current.has(dependency.key) : undefined
+  return current
+}
