+export function assertNoAtomicCircularDependencies(logic: BuiltLogic): void {
+  const states = (logic as any).__keaAtomicStates as Map<string, AtomicState> | undefined
+  if (!states) return
+  topologicalOrder(states) // throws on cycles
+}
+
+function topologicalOrder(states: Map<string, AtomicState>): string[] {
+  const result: string[] = []
+  const visiting = new Set<string>()
+  const visited = new Set<string>()
+  const visit = (name: string) => {
+    if (visiting.has(name)) throw new Error('[KEA] Circular dependency detected')
+    if (visited.has(name)) return
+    visiting.add(name)
+    for (const dependency of states.get(name)?.selectorDependencies || []) visit(dependency)
+    visiting.delete(name); visited.add(name); result.push(name)
+  }
+  for (const name of states.keys()) visit(name)
+  return result
+}
